<script lang="ts">
  import type { BootstrapData } from '../bootstrap';
  import AppShell from '../components/AppShell.svelte'; import NoticeList from '../components/NoticeList.svelte';
  import { flag, number, record, records, strings, text } from '../lib/data'; import { passkeysSupported, registerPasskey } from '../lib/webauthn';
  let { data }: { data: BootstrapData } = $props();
  const csrf = $derived(text(data.csrfToken)); const users = $derived(records(data.users)); const passkeyMap = $derived(record(data.passkeys)); const totpMap = $derived(record(data.totpKeys));
  const min = $derived(number(data.passwordMin, 16)); const max = $derived(number(data.passwordMax, 256));
  let authentication = $state('passkey'); let status = $state('');
  const credentials = (id: unknown) => records(passkeyMap[String(id)]); const totp = (id: unknown) => records(totpMap[String(id)]);
  async function addPasskey(userId: number, username: string): Promise<void> { const label = prompt(`Name für den Passkey von ${username}`, 'Passkey'); if (label === null || label.trim() === '') return; status = `Passkey für ${username} wird angefordert …`; try { window.location.assign(await registerPasskey(userId, label, csrf)); } catch (error) { status = error instanceof Error ? error.message : 'Registrierung fehlgeschlagen.'; } }
  const remove = (event: SubmitEvent, label: string) => { if (!confirm(`${label} wirklich löschen?`)) event.preventDefault(); };
</script>

<AppShell title="Benutzerkonten" area="admin" csrfToken={csrf}>
  <NoticeList errors={strings(data.errors)} messages={strings(data.messages)} /><nav class="subnav"><a href="/admin">Übersicht</a><a class="active" href="/admin/users">Benutzer</a><a href="/admin/security">Sicherheit</a></nav>
  <section class="card preset-filled-surface-100-900 mt-6 p-6"><h2 class="h2">Konto anlegen</h2><form method="post" action="/admin/users/create" class="mt-5 grid gap-4"><input type="hidden" name="__csrf" value={csrf}><div class="form-grid"><label class="label"><span>Benutzername</span><input class="input" name="username" required maxlength="100" autocomplete="off"></label><label class="label"><span>Rolle</span><select class="select" name="role"><option value="admin">Administrator</option></select></label><label class="label"><span>Erste Anmeldung</span><select class="select" name="authentication" bind:value={authentication}><option value="passkey">Nur Passkey / FIDO2</option><option value="password">Passwort</option></select></label></div>{#if authentication === 'password'}<div class="form-grid"><label class="label"><span>Passwort</span><input class="input" type="password" name="password" required minlength={min} maxlength={max} autocomplete="new-password"></label><label class="label"><span>Bestätigung</span><input class="input" type="password" name="password_confirm" required minlength={min} maxlength={max} autocomplete="new-password"></label></div>{/if}<button class="btn preset-filled-primary-500" type="submit">Konto anlegen</button></form><p class="mt-3 text-sm opacity-70">Bei einem Passkey-only-Konto nach dem Anlegen direkt unten einen Passkey registrieren.</p></section>
  <p class="mt-5 text-sm" role="status">{status || (passkeysSupported() ? 'Passkey-Unterstützung erkannt.' : 'Keine Passkey-Unterstützung erkannt.')}</p>
  <div class="mt-6 grid gap-5">{#each users as user}<section class="card preset-filled-surface-100-900 p-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="h2">{text(user.username)}</h2><p class="mt-1 opacity-70">ID {String(user.id)} · {text(user.role)} · angelegt {text(user.created_at)}</p></div><button class="btn preset-tonal-primary" type="button" onclick={() => addPasskey(number(user.id), text(user.username))} disabled={!passkeysSupported()}>Passkey hinzufügen</button></div><form method="post" action={`/admin/users/${String(user.id)}/update`} class="form-grid mt-5"><input type="hidden" name="__csrf" value={csrf}><input type="hidden" name="role" value="admin"><label class="flex items-center gap-3"><input class="checkbox" type="hidden" name="password_login_enabled" value="0"><input class="checkbox" type="checkbox" name="password_login_enabled" value="1" checked={flag(user.password_login_enabled)}> Passwort-Anmeldung erlauben</label><label class="label"><span>Neues Passwort (optional)</span><input class="input" type="password" name="new_password" minlength={min} maxlength={max} autocomplete="new-password"></label><button class="btn preset-tonal" type="submit">Konto aktualisieren</button></form><div class="credential-grid mt-5">{#each credentials(user.id) as passkey}<article class="credential-card"><h3 class="font-bold">{text(passkey.label)}</h3><p class="mt-1 text-sm">{text(passkey.kind)}</p><p class="mt-1 text-xs opacity-70">{Array.isArray(passkey.transports) && passkey.transports.length ? passkey.transports.join(', ') : 'Transporte nicht gemeldet'} · {text(passkey.aaguid, 'keine AAGUID')}</p><form method="post" action={`/admin/users/${String(user.id)}/passkeys/${String(passkey.id)}/update`} class="mt-3 flex gap-2"><input type="hidden" name="__csrf" value={csrf}><input class="input" name="label" value={text(passkey.label)} required maxlength="100"><button class="btn preset-tonal" type="submit">Name speichern</button></form><form method="post" action={`/admin/users/${String(user.id)}/passkeys/${String(passkey.id)}/delete`} class="mt-2" onsubmit={(event) => remove(event, text(passkey.label))}><input type="hidden" name="__csrf" value={csrf}><button class="btn preset-tonal-error" type="submit">Passkey löschen</button></form></article>{/each}</div>{#if totp(user.id).length > 0}<details class="mt-5"><summary class="cursor-pointer font-semibold">TOTP-Schlüssel ({totp(user.id).length})</summary><div class="mt-3 grid gap-2">{#each totp(user.id) as key}<form method="post" action={`/admin/users/${String(user.id)}/totp-keys/${String(key.id)}/delete`} class="actions-row" onsubmit={(event) => remove(event, `TOTP ${text(key.label)}`)}><input type="hidden" name="__csrf" value={csrf}><span>{text(key.label)} · {flag(key.is_active) ? 'aktiv' : 'inaktiv'}</span><button class="btn preset-tonal-error" type="submit">Löschen</button></form>{/each}</div></details>{/if}{#if number(user.id) !== number(data.currentUserId)}<form method="post" action={`/admin/users/${String(user.id)}/delete`} class="mt-5" onsubmit={(event) => remove(event, `Konto ${text(user.username)}`)}><input type="hidden" name="__csrf" value={csrf}><button class="btn preset-tonal-error" type="submit">Konto löschen</button></form>{/if}</section>{/each}</div>
</AppShell>
